#define STANDARD
#define USE_CLEARCOAT
#define USE_UV

#ifdef PHYSICAL
#define IOR
#define SPECULAR
#endif
varying vec2 vUvOverlapped;
varying vec2 vUvPacked;
uniform vec3 diffuse;
uniform vec3 emissive;
uniform float roughness;
uniform float metalness;
uniform float opacity;
uniform float hiddenness;
uniform sampler2D u_numberMap;
uniform sampler2D u_faceMap;
uniform vec3 number;
uniform vec3 numberOutline;
uniform float dissolve;
uniform vec3 face;
uniform float numberOpacity;
uniform float outlineOpacity;

#ifdef IOR
uniform float ior;
#endif

#ifdef SPECULAR
uniform float specularIntensity;
uniform vec3 specularColor;

#ifdef USE_SPECULARINTENSITYMAP
uniform sampler2D specularIntensityMap;
#endif

#ifdef USE_SPECULARCOLORMAP
uniform sampler2D specularColorMap;
#endif
#endif

#ifdef USE_CLEARCOAT
uniform float clearcoat;
uniform float clearcoatRoughness;
#endif

#ifdef USE_SHEEN
uniform vec3 sheenColor;
uniform float sheenRoughness;

#ifdef USE_SHEENCOLORMAP
uniform sampler2D sheenColorMap;
#endif

#ifdef USE_SHEENROUGHNESSMAP
uniform sampler2D sheenRoughnessMap;
#endif
#endif

varying vec3 vViewPosition;

#include <common>
#include <packing>
#include <dithering_pars_fragment>
#include <color_pars_fragment>
#include <uv_pars_fragment>
#include <uv2_pars_fragment>
#include <map_pars_fragment>
